#!/usr/bin/env python3
"""Build LOGS/final_five_tables/table5/table5_phase2.tex (post-confirmation)."""
from __future__ import annotations

import json
from pathlib import Path

REPO = Path(__file__).resolve().parents[3]
T5 = REPO / "LOGS/final_five_tables/table5"


def main() -> int:
    conf = json.loads((T5 / "phase2_confirmation.json").read_text())
    router = json.loads((T5 / "panelb_router_gpu.json").read_text())
    mcp = conf["legacy"]["mcp"]["seed_level"]
    sealed = conf["sealed"]["per_seed"]
    lines = [
        "% Phase 2 appendix table. AUTO-GENERATED by build_table5_phase2_tex.py.",
        "\\begin{table}[t]",
        "\\centering",
        "\\small",
        "\\caption{Negative-transfer fixes and routing improvements are \\emph{not} "
        "confirmed on unseen data. (top) MCP legacy replication; (middle) sealed "
        "group-isolated MCP split that was never used during development (CPU branch, "
        "all methods same hardware); (bottom) fixed-pool router comparison on GPU. "
        "`--` = not run. B_gate and A_moddrop were frozen on dev before any test was read.}",
        "\\label{tab:table5_phase2}",
        "\\begin{tabular}{@{}lcccc@{}}",
        "\\toprule",
        "\\multicolumn{5}{@{}l}{\\textbf{Legacy MCP (5 folds $\\times$ 3 seeds, GPU): "
        "seed-level AUROC}} \\\\",
        "\\midrule",
        "\\textit{Method} & 211 & 212 & 213 & mean \\\\",
        "\\midrule",
    ]
    for name in ("full", "structure_only", "chrono_only", "text_only", "B_gate",
                 "A_moddrop_0.1"):
        d = mcp.get(name)
        if not d:
            continue
        star = "$^*$" if name in ("B_gate", "A_moddrop_0.1") else ""
        per = d["per_seed"]
        lines.append(f"{name}{star} & {per['211']:.3f} & {per['212']:.3f} & "
                     f"{per['213']:.3f} & {d['mean']:.3f} \\\\")
    lines += ["\\midrule",
              "\\multicolumn{5}{@{}l}{\\textbf{Sealed group-isolated MCP split (CPU): "
              "AUROC}} \\\\",
              "\\midrule",
              "\\textit{Method} & 211 & 212 & 213 & mean \\\\",
              "\\midrule"]
    for name in ("full", "structure_only", "chrono_only", "text_only", "B_gate",
                 "A_moddrop_0.1"):
        d = sealed.get(name)
        if not d:
            continue
        lines.append(f"{name} & {d['211']:.3f} & {d['212']:.3f} & {d['213']:.3f} & "
                     f"{d['mean']:.3f} \\\\")
    lines += ["\\midrule",
              "\\multicolumn{5}{@{}l}{\\textbf{Fixed-pool router comparison "
              "(GPU, 2 orders $\\times$ 3 seeds)}} \\\\",
              "\\midrule",
              "\\textit{Strategy} & ACC & $F_T$ & active experts \\\\",
              "\\midrule"]
    for name, s in router["summary"].items():
        act = "--" if s["avg_active_experts"] is None else f"{s['avg_active_experts']:.2f}"
        lines.append(f"{name} & {s['final_macro_acc_mean']:.3f} & "
                     f"{s['forgetting_mean']:.3f} & {act} \\\\")
    lines += ["\\bottomrule", "\\end{tabular}",
              "\\par\\vspace{2pt}{\\footnotesize $^*$Frozen selection; both fail "
              "confirmation: B_gate collapses on the sealed split (0.495 vs full 0.590); "
              "on legacy MCP it ties structure-only ($-0.0004$) while a dev-fitted "
              "fixed-weight fusion of its own branches beats the learned gate on all 3 "
              "seeds. All-expert aggregation dominates every routing strategy in ACC.}",
              "\\end{table}", ""]
    (T5 / "table5_phase2.tex").write_text("\n".join(lines))
    print("wrote", T5 / "table5_phase2.tex")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
